from invoices.model import Invoice, Line
from invoices.totals import average_line_price


def test_single_line_returns_its_unit_price():
    assert average_line_price(Invoice((Line("Tea", 3, 250),))) == 250


def test_mean_of_unit_prices_ignores_quantity():
    invoice = Invoice((Line("Tea", 10, 100), Line("Cake", 1, 300)))
    assert average_line_price(invoice) == 200


