    assert average_line_price(invoice) == 100  # 100.33 -> 100


def test_rounds_negative_half_away_from_zero():
    invoice = Invoice((Line("Credit", 1, -100), Line("Credit", 1, -101)))
    assert average_line_price(invoice) == -101  # -100.5 -> -101


